create extension if not exists pgcrypto;
create type public.staff_role as enum ('staff','manager','admin');
create type public.bed_status as enum ('Available','Occupied');
create type public.payment_status as enum ('Paid','Due');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,role public.staff_role not null default 'staff',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.rooms(id uuid primary key default gen_random_uuid(),number text not null unique,type text not null default 'Shared',capacity int not null default 1 check(capacity>0),rent numeric(12,2) not null default 0 check(rent>=0),created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.students(id uuid primary key default gen_random_uuid(),name text not null,phone text not null,guardian text,course text,join_date date not null default current_date,monthly_rent numeric(12,2) not null default 0 check(monthly_rent>=0),notes text,room_id uuid references public.rooms(id) on delete set null,bed_id uuid,room text,bed text,created_by uuid references auth.users(id),updated_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.beds(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms(id) on delete cascade,label text not null,status public.bed_status not null default 'Available',student_id uuid references public.students(id) on delete set null,student_name text,allocated_at timestamptz,allocated_by uuid references auth.users(id),created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(room_id,label));
alter table public.students drop constraint if exists students_bed_id_fkey;
alter table public.students add constraint students_bed_id_fkey foreign key(bed_id) references public.beds(id) on delete set null;
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.students(id) on delete restrict,student_name text,amount numeric(12,2) not null check(amount>0),status public.payment_status not null default 'Paid',date date not null default current_date,method text not null default 'Cash',reference text,note text,recorded_by uuid references auth.users(id),recorded_by_email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),date date not null default current_date,category text not null,amount numeric(12,2) not null check(amount>0),vendor text,description text not null,note text,recorded_by uuid references auth.users(id),recorded_by_email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),action text not null,actor_id uuid references auth.users(id),target_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists beds_room_id_idx on public.beds(room_id); create index if not exists payments_student_id_idx on public.payments(student_id); create index if not exists expenses_date_idx on public.expenses(date desc);
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
DO $$ DECLARE t text; BEGIN FOR t IN SELECT unnest(ARRAY['profiles','rooms','students','beds','payments','expenses']) LOOP EXECUTE format('drop trigger if exists touch_updated_at on public.%I',t); EXECUTE format('create trigger touch_updated_at before update on public.%I for each row execute function public.touch_updated_at()',t); END LOOP; END $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email) values(new.id,new.email) on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.my_role() returns public.staff_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid(); $$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select public.my_role() in ('staff','manager','admin'); $$;
create or replace function public.is_manager() returns boolean language sql stable security definer set search_path=public as $$ select public.my_role() in ('manager','admin'); $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select public.my_role()='admin'; $$;
create or replace function public.allocate_bed(p_student_id uuid,p_bed_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare b public.beds%rowtype; s public.students%rowtype; r public.rooms%rowtype; begin if not public.is_staff() then raise exception 'Permission denied'; end if; select * into b from public.beds where id=p_bed_id for update; if not found or b.status<>'Available' then raise exception 'Bed is no longer available'; end if; select * into s from public.students where id=p_student_id for update; if not found then raise exception 'Student not found'; end if; select * into r from public.rooms where id=b.room_id; if not found then raise exception 'Room not found'; end if; if s.bed_id is not null then update public.beds set status='Available',student_id=null,student_name=null,allocated_at=null,allocated_by=null where id=s.bed_id; end if; update public.beds set status='Occupied',student_id=p_student_id,student_name=s.name,allocated_at=now(),allocated_by=auth.uid() where id=p_bed_id; update public.students set room_id=r.id,room=r.number,bed_id=b.id,bed=b.label,updated_by=auth.uid() where id=p_student_id; insert into public.audit_logs(action,actor_id,target_id,details) values('ALLOCATE_BED',auth.uid(),p_student_id,jsonb_build_object('bed_id',p_bed_id,'room',r.number,'bed',b.label)); return jsonb_build_object('ok',true); end; $$;
create or replace function public.release_bed(p_student_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare oldbed uuid; begin if not public.is_staff() then raise exception 'Permission denied'; end if; select bed_id into oldbed from public.students where id=p_student_id for update; if oldbed is not null then update public.beds set status='Available',student_id=null,student_name=null,allocated_at=null,allocated_by=null where id=oldbed; end if; update public.students set room_id=null,room=null,bed_id=null,bed=null,updated_by=auth.uid() where id=p_student_id; insert into public.audit_logs(action,actor_id,target_id,details) values('RELEASE_BED',auth.uid(),p_student_id,jsonb_build_object('bed_id',oldbed)); return jsonb_build_object('ok',true); end; $$;
create or replace function public.bootstrap_first_admin() returns jsonb language plpgsql security definer set search_path=public as $$
begin
  if auth.uid() is null then raise exception 'You must be signed in'; end if;
  if exists(select 1 from public.profiles where role='admin') then raise exception 'An admin already exists'; end if;
  update public.profiles set role='admin', updated_at=now() where id=auth.uid();
  if not found then raise exception 'Your profile was not created yet. Sign out and sign in again.'; end if;
  return jsonb_build_object('ok',true,'email',(select email from public.profiles where id=auth.uid()));
end; $$;
create or replace function public.set_staff_role(p_user_id uuid,p_role public.staff_role) returns jsonb language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'Admin role required'; end if; update public.profiles set role=p_role where id=p_user_id; if not found then raise exception 'Profile not found'; end if; insert into public.audit_logs(action,actor_id,target_id,details) values('SET_STAFF_ROLE',auth.uid(),p_user_id,jsonb_build_object('role',p_role)); return jsonb_build_object('ok',true); end; $$;
grant execute on function public.allocate_bed(uuid,uuid),public.release_bed(uuid),public.set_staff_role(uuid,public.staff_role) to authenticated;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rooms ENABLE ROW LEVEL SECURITY; ALTER TABLE public.students ENABLE ROW LEVEL SECURITY; ALTER TABLE public.beds ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy rooms_read on public.rooms for select to authenticated using(public.is_staff()); create policy rooms_insert on public.rooms for insert to authenticated with check(public.is_manager()); create policy rooms_update on public.rooms for update to authenticated using(public.is_manager()) with check(public.is_manager()); create policy rooms_delete on public.rooms for delete to authenticated using(public.is_admin());
create policy students_read on public.students for select to authenticated using(public.is_staff()); create policy students_insert on public.students for insert to authenticated with check(public.is_staff() and created_by=auth.uid()); create policy students_update on public.students for update to authenticated using(public.is_staff()) with check(public.is_staff()); create policy students_delete on public.students for delete to authenticated using(public.is_manager());
create policy beds_read on public.beds for select to authenticated using(public.is_staff()); create policy beds_insert on public.beds for insert to authenticated with check(public.is_manager() and created_by=auth.uid()); create policy beds_update on public.beds for update to authenticated using(public.is_manager()) with check(public.is_manager()); create policy beds_delete on public.beds for delete to authenticated using(public.is_admin());
create policy payments_read on public.payments for select to authenticated using(public.is_staff()); create policy payments_insert on public.payments for insert to authenticated with check(public.is_staff() and recorded_by=auth.uid()); create policy payments_update on public.payments for update to authenticated using(public.is_manager()) with check(public.is_manager()); create policy payments_delete on public.payments for delete to authenticated using(public.is_admin());
create policy expenses_read on public.expenses for select to authenticated using(public.is_staff()); create policy expenses_insert on public.expenses for insert to authenticated with check(public.is_staff() and recorded_by=auth.uid()); create policy expenses_update on public.expenses for update to authenticated using(public.is_manager()) with check(public.is_manager()); create policy expenses_delete on public.expenses for delete to authenticated using(public.is_admin());
create policy audit_read on public.audit_logs for select to authenticated using(public.is_admin());
-- After creating the first Auth user, bootstrap admin with:
